	'messages:apihelp-unblock-param-user' => 'en:User to unblock. Cannot be used together with <var>$1id</var>.',
	'messages:apihelp-unblock-param-userid' => 'en:Specify <kbd>$1user=#<var>ID</var></kbd> instead.',
	'messages:apihelp-unblock-param-reason' => 'en:Reason for unblock.',
	'messages:apihelp-unblock-param-tags' => 'en:Change tags to apply to the entry in the block log.',
